default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Microsoft\Windows Nt\CurrentVersion\Winlogon' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('AutoAdminLogon', $null, 'DoNotExpandEnvironmentNames') }
$kind = $null
if ($null -ne $current) { $kind = $key.GetValueKind('AutoAdminLogon') }
if (-not ($current -is [string] -and $kind -ceq 'String' -and $current -ceq '0')) {
    Write-Output 'Mismatch: HKLM:\Software\Microsoft\Windows Nt\CurrentVersion\Winlogon [AutoAdminLogon]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Microsoft\Windows Nt\CurrentVersion\Winlogon')) {
    New-Item -Path 'HKLM:\Software\Microsoft\Windows Nt\CurrentVersion\Winlogon' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Microsoft\Windows Nt\CurrentVersion\Winlogon' -Name 'AutoAdminLogon' -Value '0' -PropertyType String -Force | Out-Null
exit 0
